#!/usr/bin/env bash
# Test setup.sh on a fake Hermes home with a stub `hermes`: hook installed, config gets
# hooks once (re-run safe), existing hooks are not overwritten, settings are applied.
set -euo pipefail
cd "$(dirname "$0")"
T=$(mktemp -d); trap 'rm -rf "$T"' EXIT
fail() { echo "FAIL: $*"; exit 1; }
mkdir -p "$T/h/profiles/second" "$T/bin"
printf 'model:\n  default: x\nhooks_auto_accept: false\n' > "$T/h/config.yaml"
printf 'hooks:\n  pre_tool_call: []\ncompression:\n  enabled: true\n  threshold: 0.75\n  target_ratio: 0.2\n' > "$T/h/profiles/second/config.yaml"
printf '#!/bin/sh\necho "$*" >> %s/calls\n' "$T" > "$T/bin/hermes"; chmod +x "$T/bin/hermes"
printf "# Агент\n" > "$T/h/SOUL.md"
run() { HERMES_SRC="$T/nosrc" HERMES_DIR="$T/h" HERMES_BIN="$T/bin/hermes" PROTECT_SRC="$PWD/protect-home.py" GATE_SRC="$PWD/verify-gate.py" MC_SRC="$PWD/media-check" BA_SRC="$PWD/busy-ack-ru" FI_SRC="$PWD/facts-inject" bash setup.sh; }
out=$(run) || fail "setup failed: $out"
[ -x "$T/h/hooks/protect-home.py" ] || fail "hook not installed"
grep -q "command: $T/h/hooks/protect-home.py" "$T/h/config.yaml" || fail "hook not in config"
[ "$(grep -c '^hooks_auto_accept: true' "$T/h/config.yaml")" = 1 ] || fail "auto_accept"
grep -q "protect-home" "$T/h/profiles/second/config.yaml" && fail "overwrote existing hooks"
echo "$out" | grep -q "ВНИМАНИЕ" || fail "no warning for existing hooks"
grep -q "session_reset.mode both --force" "$T/calls" && grep -q "display.show_commentary false --force" "$T/calls" || fail "settings not applied"
[ -x "$T/h/hooks/verify-gate.py" ] || fail "gate not installed"
grep -q "verify-gate.py" "$T/h/config.yaml" || fail "gate not in main config"
grep -q "verify-gate.py" "$T/h/profiles/second/config.yaml" || fail "gate not added next to existing hooks"
grep -q "Проверка перед «готово»" "$T/h/SOUL.md" || fail "rule not in SOUL"
grep -q "Спросить другого агента = передать и ждать" "$T/h/SOUL.md" && grep -q "Заметки — коротко и по местам" "$T/h/SOUL.md" || fail "GPT rules (13.11) not in SOUL"
[ "$(grep -c "Спросить другого агента = передать и ждать" "$T/h/SOUL.md")" = 1 ] || fail "GPT rules duplicated"
grep -q "## Длина ответа владельцу" "$T/h/SOUL.md" || fail "length rule not in SOUL"
[ -f "$T/h/plugins/media-check/__init__.py" ] && [ -f "$T/h/profiles/second/plugins/media-check/plugin.yaml" ] || fail "media-check not installed"
grep -q "plugins enable media-check" "$T/calls" && grep -q -- "--profile second plugins enable media-check" "$T/calls" || fail "media-check not enabled"
grep -A3 '^compression:' "$T/h/profiles/second/config.yaml" | grep -q 'threshold: 0.1$' || fail "profile compression not lowered"
grep -A4 '^compression:' "$T/h/profiles/second/config.yaml" | grep -q 'threshold_tokens: 100000$' || fail "profile cap missing"
grep -A4 '^compression:' "$T/h/config.yaml" | grep -q 'threshold_tokens: 100000$' || fail "main cap missing"
grep -q 'target_ratio: 0.2' "$T/h/profiles/second/config.yaml" || fail "compression block damaged"
grep -A3 '^compression:' "$T/h/config.yaml" | grep -q 'threshold: 0.1$' || fail "main compression not added"
[ -f "$T/h/plugins/busy-ack-ru/__init__.py" ] && [ -f "$T/h/profiles/second/plugins/busy-ack-ru/plugin.yaml" ] || fail "busy-ack-ru not installed"
grep -q -- "--profile second plugins enable busy-ack-ru" "$T/calls" || fail "busy-ack-ru not enabled"
[ -f "$T/h/profiles/second/plugins/facts-inject/__init__.py" ] && grep -q "tz=3" "$T/h/profiles/second/plugins/facts-inject/facts.txt" || fail "facts-inject not installed"
grep -q -- "--profile second plugins enable facts-inject" "$T/calls" || fail "facts-inject not enabled"
grep -q "^config set display.busy_input_mode steer --force" "$T/calls" || fail "main steer mode"
grep -q -- "--profile second config set display.busy_input_mode steer --force" "$T/calls" || fail "profile steer mode"
grep -q -- "--profile second config set display.show_commentary false --force" "$T/calls" || fail "quiet mode not on second profile"
run >/dev/null
[ "$(grep -c '^compression:' "$T/h/config.yaml")" = 1 ] || fail "re-run duplicated compression"
[ "$(grep -c 'threshold_tokens:' "$T/h/profiles/second/config.yaml")" = 1 ] || fail "re-run duplicated cap"
[ "$(grep -c 'verify-gate.py' "$T/h/config.yaml")" = 1 ] || fail "re-run duplicated gate"
[ "$(grep -c 'Проверка перед «готово»' "$T/h/SOUL.md")" = 1 ] || fail "re-run duplicated rule"
grep -q "Что важнее, если правила спорят" "$T/h/SOUL.md" || fail "priority rule not in SOUL"
[ "$(grep -c 'Что важнее, если правила спорят' "$T/h/SOUL.md")" = 1 ] || fail "re-run duplicated priority rule"
[ "$(grep -c '^hooks:' "$T/h/config.yaml")" = 1 ] || fail "re-run duplicated hooks"
# Fresh Hermes 0.23 template: column-0 comments inside compression and its own threshold
# further down; also a config already broken by the old script (two threshold keys).
T2=$(mktemp -d); trap 'rm -rf "$T" "$T2"' EXIT
mkdir -p "$T2/h"
printf 'model:\n  default: x\ncompression:\n  threshold_tokens: 100000\n  threshold: 0.1\n  enabled: true\n# top-level comment inside the block\n  threshold: 0.50\n  target_ratio: 0.20\ndisplay:\n  x: 1\n' > "$T2/h/config.yaml"
printf "# Агент\n" > "$T2/h/SOUL.md"
HERMES_SRC="$T/nosrc" HERMES_DIR="$T2/h" HERMES_BIN="$T/bin/hermes" PROTECT_SRC="$PWD/protect-home.py" GATE_SRC="$PWD/verify-gate.py" MC_SRC="$PWD/media-check" BA_SRC="$PWD/busy-ack-ru" FI_SRC="$PWD/facts-inject" bash setup.sh >/dev/null || fail "setup failed on template config"
[ "$(grep -c '^  threshold:' "$T2/h/config.yaml")" = 1 ] || fail "duplicate threshold not repaired"
grep -q '^  threshold: 0.1$' "$T2/h/config.yaml" || fail "template threshold not lowered"
[ "$(grep -c '^  threshold_tokens:' "$T2/h/config.yaml")" = 1 ] || fail "duplicate cap"
python3 -c "import yaml,sys; d=yaml.safe_load(open(sys.argv[1])); assert d['compression']['threshold']==0.1 and d['compression']['target_ratio']==0.2 and d['display']['x']==1" "$T2/h/config.yaml" || fail "config not valid YAML after repair"
# Old Hermes: no session-reset plugin. New Hermes (source says the setting "is no longer applied"): plugin in every profile.
grep -q "hermes-session-reset-policy" "$T/calls" && fail "session-reset plugin installed on old Hermes"
mkdir -p "$T/newsrc/hermes_cli"; echo 'MSG = "session_reset is no longer applied"' > "$T/newsrc/hermes_cli/session_reset_retirement.py"
: > "$T/calls"
HERMES_SRC="$T/newsrc" HERMES_DIR="$T/h" HERMES_BIN="$T/bin/hermes" PROTECT_SRC="$PWD/protect-home.py" GATE_SRC="$PWD/verify-gate.py" MC_SRC="$PWD/media-check" BA_SRC="$PWD/busy-ack-ru" FI_SRC="$PWD/facts-inject" bash setup.sh >/dev/null || fail "setup failed on new Hermes"
grep -qx "plugins install hermes-session-reset-policy" "$T/calls" && grep -qx "plugins enable hermes-session-reset-policy" "$T/calls" || fail "session-reset plugin not set up in main profile"
grep -q -- "--profile second plugins enable hermes-session-reset-policy" "$T/calls" || fail "session-reset plugin not enabled in second profile"
echo "ALL TESTS PASSED"
